export const specializationMap = new Map<string, SpecializationRecord>(
  industrySpecializations.map(s => [`${s.industryId}/${s.id}`, s])
);

export function getSpecializationsForIndustry(industryId: string): SpecializationRecord[] {
  return industrySpecializations.filter(s => s.industryId === industryId);
}

export function getSpecialization(industryId: string, id: string): SpecializationRecord | undefined {
  return specializationMap.get(`${industryId}/${id}`);
}

export function specializationPath(lang: string, industryId: string, id: string): string {
  return `/${lang}/industries/${industryId}/${id}/`;
}

export function specializationAlternates(industryId: string, id: string): Record<string, string> {
  const alts = Object.fromEntries(
    activeLocales.map(lang => [lang, `https://ctseg.com.tr${specializationPath(lang, industryId, id)}`])
  );
  alts['x-default'] = `https://ctseg.com.tr${specializationPath('en', industryId, id)}`;
  return alts;
}
